def bump_major(self) -> "VersionInfo":
    """Return a new :class:`VersionInfo` with the major component incremented
    and the minor and patch components reset to ``0``.
    """
    return self.replace(major=self.major + 1, minor=0, patch=0, build=None)

def bump_minor(self) -> "VersionInfo":
    """Return a new :class:`VersionInfo` with the minor component
    incremented and the patch component reset to ``0``.
    """
    return self.replace(minor=self.minor + 1, patch=0, build=None)

def bump_patch(self) -> "VersionInfo":
    """Return a new :class:`VersionInfo` with the patch component
    incremented.
    """
    return self.replace(patch=self.patch + 1, build=None)

def bump_prerelease(self, prerelease_prefix: str | None = None) -> "VersionInfo":
    """Return a new :class:`VersionInfo` with the pre‑release part
    incremented.  The build metadata is discarded.
    """
    token = prerelease_prefix or "rc"
    pre = self.prerelease
    if pre is None:
        new_pre = f"{token}.1"
    else:
        new_pre = _increment_numeric_in_string(pre)
    return self.replace(prerelease=new_pre, build=None)

def bump_build(self, token: str | None = None) -> "VersionInfo":
    """Return a new :class:`VersionInfo` with the build metadata
    incremented.  The pre‑release part is preserved.
    """
    if self.build is None:
        new_build = f"{token or 'build'}.1"
    else:
        new_build = _increment_numeric_in_string(self.build)
    return self.replace(build=new_build)
